mapper.select:
SELECT a.uuid, a.attachment_id, a.attachment_path, a.original_filename, a.access_key, a.create_time, a.deleted_time, a.status, u.username
FROM attachment a
JOIN user_information u ON a.uuid = u.uuid
WHERE a.status = 0 AND a.deleted_time >= #{cutoff}
ORDER BY a.deleted_time DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM attachment
WHERE status = 0 AND deleted_time >= #{cutoff}

SELECT a.uuid, a.attachment_id, a.original_filename, a.attachment_path, a.access_key, a.create_time, a.deleted_time, a.status, u.username
FROM attachment a
JOIN user_information u ON a.uuid = u.uuid
WHERE a.status = 0 AND a.deleted_time >= #{cutoff}
  AND a.uuid = #{uuid}
ORDER BY a.deleted_time DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM attachment
WHERE status = 0 AND deleted_time >= #{cutoff}
  AND uuid = #{uuid}

SELECT a.uuid, a.attachment_id, a.original_filename, a.attachment_path, a.access_key, a.create_time, a.deleted_time, a.status, u.username
FROM attachment a
JOIN user_information u ON a.uuid = u.uuid
WHERE a.status = 0 AND a.deleted_time >= #{cutoff}
  AND a.uuid = #{userUuid}
ORDER BY a.deleted_time DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM attachment
WHERE status = 0 AND deleted_time >= #{cutoff}
  AND uuid = #{userUuid}

